<?php namespace Inilim\Tool\Method\String;\Inilim\Tool\Str :: __include(['ascii','lower']);function slug(string $title,string $separator='-',?string $language='en',array $dictionary=['@'=>'at']):string{$title=$language?ascii($title,$language):$title;$flip=$separator==='-'?'_':'-';$title=\preg_replace('!['.\preg_quote($flip).']+!u',$separator,$title);foreach($dictionary as $key=>$value){$dictionary[$key]=$separator.$value.$separator;}$title=\str_replace(\array_keys($dictionary),\array_values($dictionary),$title);$title=\preg_replace('![^'.\preg_quote($separator).'\pL\pN\s]+!u','',lower($title));$title=\preg_replace('!['.\preg_quote($separator).'\s]+!u',$separator,$title);return \trim($title,$separator);}